WHERE s.business_domain_id = #{domainId}

    AND s.session_status = #{status}

ORDER BY s.updated_at DESC, s.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM consultation_session
WHERE business_domain_id = #{domainId}

    AND session_status = #{status}


WHERE s.business_domain_id = #{domainId}
  AND s.customer_id = #{customerId}
ORDER BY s.updated_at DESC, s.id DESC

SELECT COALESCE(MAX(CAST(SUBSTRING(session_no, 3) AS UNSIGNED)), 0) + 1
FROM consultation_session
WHERE session_no LIKE #{prefix}

SELECT COALESCE(MAX(seq_no), 0) + 1
FROM consultation_message
WHERE consultation_session_id = #{sessionId}

mapper.update:
UPDATE consultation_session
SET last_message_at = #{lastMessageAt}
WHERE id = #{sessionId}

UPDATE consultation_session
SET assigned_to = #{assignedTo}
WHERE id = #{sessionId}
  AND assigned_to IS NULL

UPDATE consultation_session
SET session_status = 'closed',
    closed_at = #{closedAt}
WHERE id = #{sessionId}
  AND session_status <> 'closed'

